NASHR_CONSOLE_HTML = "<!DOCTYPE html>\n<html lang=\"ar\" dir=\"rtl\">\n<head>\n<meta charset=\"UTF-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>Nashr Console</title>\n<script src=\"https://cdn.tailwindcss.com\"></script><script>tailwind.config={darkMode:'class'};</script>\n</head>\n<body class=\"min-h-screen bg-slate-50 text-slate-900 antialiased dark:bg-slate-950 dark:text-slate-100\">\n<main class=\"mx-auto max-w-5xl px-4 py-8 sm:px-6 lg:px-8\">\n<header class=\"mb-8 flex items-center justify-between gap-4\"><div><p class=\"text-sm font-medium text-indigo-600 dark:text-indigo-400\">Nashr</p><h1 class=\"mt-1 text-3xl font-bold\">Nashr Console</h1><p class=\"mt-2 text-sm text-slate-600 dark:text-slate-400\">رفع PDF، استخراج الأفكار، ثم نشر الفكرة المختارة في تيليجرام.</p></div><button id=\"theme-toggle\" class=\"rounded-xl border border-slate-200 bg-white px-3 py-2 text-sm shadow-sm dark:border-slate-800 dark:bg-slate-900\">◐ الوضع</button></header>\n<section class=\"rounded-2xl border border-slate-200 bg-white p-5 shadow-sm dark:border-slate-800 dark:bg-slate-900\">\n<div class=\"flex flex-col gap-4 sm:flex-row sm:items-end\"><label class=\"flex-1\"><span class=\"mb-2 block text-sm font-semibold\">ملف PDF</span><input id=\"pdf-file\" type=\"file\" accept=\"application/pdf\" class=\"block w-full rounded-xl border border-slate-300 bg-slate-50 p-3 text-sm dark:border-slate-700 dark:bg-slate-950\"></label><button id=\"upload-btn\" class=\"rounded-xl bg-indigo-600 px-6 py-3 font-semibold text-white disabled:opacity-50\">رفع واستخراج</button></div>\n<div id=\"progress\" class=\"mt-5 hidden\"><div class=\"flex items-center gap-3 text-sm text-slate-600 dark:text-slate-400\"><span class=\"h-4 w-4 animate-spin rounded-full border-2 border-indigo-500 border-t-transparent\"></span><span id=\"progress-text\"></span></div></div>\n<div id=\"error\" class=\"mt-4 hidden rounded-xl border border-red-200 bg-red-50 p-3 text-sm text-red-700 dark:border-red-900 dark:bg-red-950/30 dark:text-red-300\"></div>\n</section>\n<section id=\"ideas-section\" class=\"mt-8 hidden\"><div class=\"mb-4 flex items-end justify-between\"><div><h2 class=\"text-xl font-bold\">الأفكار الخمس</h2><p class=\"mt-1 text-sm text-slate-500\">اختر فكرة لإنشاء المسودة.</p></div><span id=\"idea-count\" class=\"rounded-full bg-slate-100 px-3 py-1 text-xs dark:bg-slate-800\"></span></div><div id=\"ideas\" class=\"grid gap-4 md:grid-cols-2\"></div></section>\n<section id=\"draft-section\" class=\"mt-8 hidden\"><div class=\"rounded-2xl border border-indigo-200 bg-indigo-50/70 p-5 dark:border-indigo-900 dark:bg-indigo-950/30\"><h2 class=\"text-xl font-bold\">معاينة ونشر</h2><div id=\"draft-content\" class=\"mt-4 whitespace-pre-wrap rounded-xl border border-indigo-100 bg-white p-4 text-sm leading-7 dark:border-indigo-900 dark:bg-slate-950\"></div><button id=\"publish-btn\" class=\"mt-5 w-full rounded-xl bg-emerald-600 px-6 py-4 text-lg font-bold text-white disabled:opacity-50\">🚀 نشر في تيليجرام</button></div></section>\n<section id=\"success-section\" class=\"mt-8 hidden\"><div class=\"rounded-2xl border border-emerald-200 bg-emerald-50 p-6 dark:border-emerald-900 dark:bg-emerald-950/30\"><h2 class=\"text-xl font-bold text-emerald-800 dark:text-emerald-300\">✓ تم النشر بنجاح</h2><p class=\"mt-1 text-sm text-emerald-700 dark:text-emerald-400\">تم إرسال المنشور وتسجيل النتيجة في Nashr.</p><p class=\"mt-3 text-xs\">معرف رسالة تيليجرام</p><code id=\"external-id\" class=\"mt-1 block break-all rounded-lg bg-white/70 p-2 text-sm dark:bg-slate-950/60\"></code></div></section>\n</main>\n<script>\nconst $=id=>document.getElementById(id),state={publicationId:null};\nfunction busy(v,msg){$('upload-btn').disabled=v;$('publish-btn').disabled=v;$('progress').classList.toggle('hidden',!v);if(msg)$('progress-text').textContent=msg}\nfunction error(m){$('error').textContent=m;$('error').classList.remove('hidden')}\nfunction clearError(){$('error').classList.add('hidden')}\nasync function request(url,opt={}){const r=await fetch(url,opt),d=await r.json().catch(()=>({}));if(!r.ok)throw Error(d.detail||'حدث خطأ غير متوقع.');return d}\nfunction renderIdeas(ids){$('ideas').innerHTML=ids.map((id,i)=>'<button data-id=\"'+id+'\" class=\"idea-card text-right rounded-2xl border border-slate-200 bg-white p-5 shadow-sm dark:border-slate-800 dark:bg-slate-900\"><span class=\"mb-3 inline-flex h-8 w-8 items-center justify-center rounded-full bg-indigo-100 text-sm font-bold text-indigo-700 dark:bg-indigo-950 dark:text-indigo-300\">'+(i+1)+'</span><span class=\"block text-sm font-semibold\">فكرة مستخرجة</span><span class=\"mt-2 block break-all text-xs text-slate-500\">'+id+'</span></button>').join('');document.querySelectorAll('.idea-card').forEach(b=>b.onclick=()=>selectIdea(b.dataset.id,b))}\nasync function selectIdea(id,b){clearError();document.querySelectorAll('.idea-card').forEach(x=>x.classList.remove('border-indigo-500','ring-2'));b.classList.add('border-indigo-500','ring-2');busy(true,'جاري إنشاء المسودة...');try{const d=await request('/knowledge-units/'+id+'/draft',{method:'POST'});state.publicationId=d.id;$('draft-content').textContent=d.content||'';$('draft-section').classList.remove('hidden');$('draft-section').scrollIntoView({behavior:'smooth'})}catch(e){error(e.message)}finally{busy(false)}}\n$('upload-btn').onclick=async()=>{clearError();const f=$('pdf-file').files[0];if(!f){error('اختر ملف PDF أولاً.');return}const form=new FormData();form.append('file',f);$('ideas-section').classList.add('hidden');$('draft-section').classList.add('hidden');$('success-section').classList.add('hidden');busy(true,'جاري رفع الملف...');try{const s=await request('/sources',{method:'POST',body:form});busy(true,'تم الرفع. جاري استخراج 5 أفكار...');const x=await request('/sources/'+s.id+'/extract',{method:'POST'});renderIdeas(x.knowledge_unit_ids||[]);$('idea-count').textContent=(x.count||0)+' أفكار';$('ideas-section').classList.remove('hidden');$('ideas-section').scrollIntoView({behavior:'smooth'})}catch(e){error(e.message)}finally{busy(false)}}\n$('publish-btn').onclick=async()=>{if(!state.publicationId)return;clearError();busy(true,'جاري النشر في تيليجرام...');try{const r=await request('/publications/'+state.publicationId+'/publish',{method:'POST'});if(r.status!=='PUBLISHED')throw Error(r.error_message||'تعذر تأكيد النشر.');$('external-id').textContent=r.external_id||'غير متاح';$('success-section').classList.remove('hidden');$('success-section').scrollIntoView({behavior:'smooth'})}catch(e){error(e.message)}finally{busy(false)}}\n$('theme-toggle').onclick=()=>document.documentElement.classList.toggle('dark');\n</script></body></html>"
